(()=>{
const local=document.querySelector('.browser');
const tabs=document.createElement('div');tabs.className='archive-source-tabs';tabs.setAttribute('role','group');tabs.setAttribute('aria-label','자료 위치');
const localTab=document.createElement('button'),githubTab=document.createElement('button');localTab.textContent='내 보관함';githubTab.textContent='GitHub';localTab.setAttribute('aria-pressed','true');githubTab.setAttribute('aria-pressed','false');tabs.append(localTab,githubTab);local.before(tabs);
const panel=document.createElement('section');panel.className='browser github-inline-browser';panel.hidden=true;panel.setAttribute('aria-label','GitHub 자료 보관함');panel.innerHTML='<div class="toolbar"><nav class="github-crumb" aria-label="GitHub 폴더 경로"></nav><button class="github-reload">새로고침</button></div><div class="searchline"><span>⌕</span><input aria-label="GitHub 파일 검색" placeholder="현재 폴더에서 검색"></div><p class="github-status" role="status"></p><div class="github-entries"></div>';local.after(panel);
const crumb=panel.querySelector('nav'),status=panel.querySelector('[role=status]'),entries=panel.querySelector('.github-entries'),search=panel.querySelector('input');let repo=null,path='',items=[],seq=0;
const readme=document.querySelector('.readme'),localButtons=['newfolder','upload','sideadd','live-folder'];
function switchView(github){local.hidden=github;panel.hidden=!github;if(readme)readme.hidden=github;localTab.setAttribute('aria-pressed',String(!github));githubTab.setAttribute('aria-pressed',String(github));for(const id of localButtons){const el=document.getElementById(id);if(el)el.hidden=github;}}
function step(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;crumb.append(b);}
function breadcrumbs(){crumb.replaceChildren();step('GitHub',()=>{repo=null;path='';load();});if(!repo)return;step(' / '+repo.fullName,()=>{path='';load();});let prefix='';for(const part of path.split('/').filter(Boolean)){prefix+=(prefix?'/':'')+part;const target=prefix;step(' / '+part,()=>{path=target;load();});}}
function render(){entries.replaceChildren();const found=items.filter(n=>n.name.toLowerCase().includes(search.value.toLowerCase()));if(!found.length){const empty=document.createElement('p');empty.className='empty';empty.textContent=search.value?'일치하는 항목이 없습니다.':'표시할 항목이 없습니다.';entries.append(empty);return;}
for(const n of found){const row=document.createElement('div');row.className='github-entry';const link=document.createElement(n.type==='file'?'a':'button');link.className='github-entry-name';const icon=document.createElement('span');icon.textContent=n.type==='file'?'▤':'▱';const name=document.createElement('span');name.textContent=n.name;link.append(icon,name);
if(n.type==='repo')link.onclick=()=>{repo=n.repo;path='';load();};else if(n.type==='dir')link.onclick=()=>{path=n.path;load();};else{try{const u=new URL(n.url);if(u.protocol!=='https:'||u.hostname!=='github.com')continue;link.href=u.href;}catch{continue;}link.target='_blank';link.rel='noopener noreferrer';link.title='GitHub에서 파일 보기 (새 탭)';}
const kind=document.createElement('span');kind.className='muted';kind.textContent=n.type==='repo'?'저장소':n.type==='dir'?'폴더':'파일 · 새 탭 ↗';const size=document.createElement('span');size.className='muted';size.textContent=n.type==='file'?Math.ceil(n.size/1024)+' KB':'—';row.append(link,kind,size);entries.append(row);}}
async function load(){const version=++seq;items=[];search.value='';entries.replaceChildren();breadcrumbs();status.textContent='불러오는 중입니다…';try{await ServerArchive.session();if(!repo){const r=await ServerArchive.api('/assistant/repositories');if(version!==seq)return;items=r.repositories.map(r=>({name:r.fullName,type:'repo',repo:r}));status.textContent=items.length+'개 저장소 · 저장소를 열어 파일을 확인하세요.';if(!items.length)status.textContent='조회 가능한 저장소가 없습니다. GitHub 계정 관리에서 저장소 접근 권한을 확인해주세요.';}else{const r=await ServerArchive.api('/github/browse?'+new URLSearchParams({repoId:repo.id,path}));if(version!==seq)return;items=r.entries.map(n=>({...n,type:n.type==='dir'?'dir':'file'}));status.textContent=items.length+'개 항목 · 파일은 GitHub 원문으로 열립니다.'+(items.length>=1000?' 큰 폴더는 일부 항목만 표시될 수 있습니다.':'');}items.sort((a,b)=>(a.type==='file'?1:0)-(b.type==='file'?1:0)||a.name.localeCompare(b.name,'ko'));render();}catch(e){if(version===seq)status.textContent=e.message;}}
localTab.onclick=()=>switchView(false);githubTab.onclick=()=>{switchView(true);load();};panel.querySelector('.github-reload').onclick=load;search.oninput=render;
})();